/// The entries ECMF defines only for a particular revision of its own
/// table.
fn gated(
    local_tables_version: u8,
    discipline: u8,
    category: u8,
    number: u8,
) -> Option<(&'static str, &'static str, &'static str)> {
    let entry = match (local_tables_version, discipline, category, number) {
        (1, 0, 1, 254) => ("sd", "Snow depth", "m of water equivalent"),
        (1, 0, 6, 193) => ("lcc", "Low cloud cover", "(0 - 1)"),
        (1, 0, 6, 194) => ("mcc", "Medium cloud cover", "(0 - 1)"),
        (1, 0, 6, 195) => ("hcc", "High cloud cover", "(0 - 1)"),
        (1, 0, 19, 192) => ("asn", "Snow albedo", "(0 - 1)"),
        (1, 0, 20, 194) => (
            "aer_sink_mflx",
            "Aerosol sink/loss mass flux",
            "kg m**-2 s**-1",
        ),
        (1, 0, 20, 195) => (
            "vm_tc_vol_mixrat",
            "Volume-mean total column mixing ratio",
            "mol mol**-1",
        ),
        (1, 2, 0, 198) => (
            "gppbfas",
            "GPP coefficient from Biogenic Flux Adjustment System",
            "dimensionless",
        ),
        (1, 2, 0, 199) => (
            "recbfas",
            "Rec coefficient from Biogenic Flux Adjustment System",
            "dimensionless",
        ),
        (1, 2, 0, 200) => ("srlh", "Surface roughness length for heat", "m"),
        (1, 2, 0, 205) => ("src", "Skin reservoir content", "m of water equivalent"),
        (228, 0, 254, 134) => (
            "vtnowd",
            "V-tendency from non-orographic wave drag",
            "m s**-2",
        ),
        (228, 0, 254, 136) => (
            "utnowd",
            "U-tendency from non-orographic wave drag",
            "m s**-2",
        ),
        _ => return None,
    };
    Some(entry)
}
